module.exports = { winner, makeMove, chooseMove };

function winner(board) {
  const lines = [
    [0,1,2],[3,4,5],[6,7,8],
    [0,3,6],[1,4,7],[2,5,8],
    [0,4,8],[2,4,6]
  ];
  for (const [a,b,c] of lines) {
    if (board[a] && board[a] === board[b] && board[a] === board[c]) {
      return board[a];
    }
  }
  const full = board.every(cell => cell !== null);
  return full ? "draw" : null;
}

function makeMove(board, index, player) {
  if (!Number.isInteger(index) || index < 0 || index > 8) {
    throw new Error("Invalid index");
  }
  if (board[index] !== null) {
    throw new Error("Cell occupied");
  }
  if (player !== "X" && player !== "O") {
    throw new Error("Invalid player");
  }
  if (winner(board) !== null) {
    throw new Error("Game is over");
  }
  const next = board.slice();
  next[index] = player;
  return next;
}

// Deliberately incorrect repair exercise: this opponent overlooks immediate wins and forks.
function chooseMove(board, player) {
  if (winner(board) !== null) return null;
  return board.findIndex(cell => cell === null);
}
